func countSubstrings(s string) int {
    manacher := func(s string) []int {
        t := "#"
        for _, ch := range s {
            t += string(ch) + "#"
        }
        n := len(t)
        p := make([]int, n)
        l, r := 0, 0
        for i := 0; i < n; i++ {
            if i < r {
                mirror := l + (r - i)
                p[i] = min(r - i, p[mirror])
            }
            for i + p[i] + 1 < n && i - p[i] - 1 >= 0 && t[i + p[i] + 1] == t[i - p[i] - 1] {
                p[i]++
            }
            if i + p[i] > r {
                l = i - p[i]
                r = i + p[i]
            }
        }
        return p
    }

    p := manacher(s)
    res := 0
    for _, radius := range p {
        res += (radius + 1) / 2
    }
    return res
}

